// ESM imports fixed for Node.js v22+
import { eq } from "drizzle-orm";
import { combinedSchema, db } from "../client.js";
const { purchase } = combinedSchema;
export async function getPurchasesByOrganizationId(organizationId) {
    if (!db) {
        throw new Error("Database not available");
    }
    return db.query.purchase.findMany({
        where: (purchase, { eq }) => eq(purchase.organizationId, organizationId),
    });
}
export async function getPurchasesByUserId(userId) {
    if (!db) {
        throw new Error("Database not available");
    }
    return db.query.purchase.findMany({
        where: (purchase, { eq }) => eq(purchase.userId, userId),
    });
}
export async function getPurchaseById(id) {
    if (!db) {
        throw new Error("Database not available");
    }
    return db.query.purchase.findFirst({
        where: (purchase, { eq }) => eq(purchase.id, id),
    });
}
export async function getPurchaseBySubscriptionId(subscriptionId) {
    if (!db) {
        throw new Error("Database not available");
    }
    return db.query.purchase.findFirst({
        where: (purchase, { eq }) => eq(purchase.subscriptionId, subscriptionId),
    });
}
export async function createPurchase(insertedPurchase) {
    if (!db) {
        throw new Error("Database not available");
    }
    const result = await db.insert(purchase).values(insertedPurchase).returning({ id: purchase.id });
    const firstResult = result[0];
    if (!firstResult) {
        throw new Error("Failed to create purchase");
    }
    const { id } = firstResult;
    return getPurchaseById(id);
}
export async function updatePurchase(updatedPurchase) {
    if (!db) {
        throw new Error("Database not available");
    }
    const result = await db.update(purchase).set(updatedPurchase).returning({ id: purchase.id });
    const firstResult = result[0];
    if (!firstResult) {
        throw new Error("Failed to update purchase");
    }
    const { id } = firstResult;
    return getPurchaseById(id);
}
export async function deletePurchaseBySubscriptionId(subscriptionId) {
    if (!db) {
        throw new Error("Database not available");
    }
    await db.delete(purchase).where(eq(purchase.subscriptionId, subscriptionId));
}
