// ESM imports fixed for Node.js v22+
/**
 * Workspace Links Database Queries
 *
 * Query functions for the workspace_links table used in MCP authentication.
 * Workspace IDs link VS Code extension instances to authenticated users,
 * enabling tier resolution without API keys in MCP config.
 *
 * Security Enhancements (P0 - 2025-02):
 * - Tier staleness detection: Refreshes tier from DB if >24h old
 * - Link expiration: Auto-deletes expired links (90 day TTL)
 * - Prevents privilege escalation from stale cached tiers
 *
 * @packageDocumentation
 */
import { eq } from "drizzle-orm";
import { z } from "zod";
import { combinedSchema, db } from "../client.js";
import { subscriptions } from "../schema/postgres.js";
import { TIER_STALENESS_THRESHOLD_MS, WORKSPACE_LINK_TTL_MS } from "../schema/vreko/workspace-links.js";
const { workspaceLinks } = combinedSchema;
// Input validation schemas
// Supports unified 12-char hex format and legacy ws_/wsg_ + 32-char hex formats
const workspaceIdSchema = z
    .string()
    .regex(/^([a-f0-9]{12}|ws[g]?_[a-f0-9]{32})$/, "Invalid workspace ID format: must be 12-char hex (unified) or ws_/wsg_ + 32-char hex (legacy)");
const linkWorkspaceSchema = z.object({
    workspaceId: workspaceIdSchema,
    userId: z.string().min(1),
    tier: z.enum(["free", "pro", "enterprise"]).optional().default("free"),
    displayName: z.string().max(255).optional(),
    expiresAt: z.date().optional(), // P0: Allow custom expiration
});
const updateTierSchema = z.object({
    workspaceId: workspaceIdSchema,
    tier: z.enum(["free", "pro", "enterprise"]),
});
/**
 * Get workspace link by workspace ID
 *
 * @param workspaceId - The workspace ID to look up
 * @returns The workspace link if found, null otherwise
 */
export async function getWorkspaceLinkById(workspaceId) {
    if (!db) {
        throw new Error("Database not available");
    }
    // Validate workspace ID format
    const validatedId = workspaceIdSchema.parse(workspaceId);
    return await db.query.workspaceLinks.findFirst({
        // biome-ignore lint/suspicious/noExplicitAny: Drizzle query builder callback
        where: (link, { eq }) => eq(link.workspaceId, validatedId),
    });
}
/**
 * Resolve tier for a workspace ID
 *
 * Main function used by MCP server to determine user tier from workspace ID.
 * Returns "free" if workspace is not linked.
 *
 * P0 Security Enhancements:
 * - Checks link expiration (auto-deletes expired links)
 * - Checks tier staleness (refreshes from DB if >24h old)
 * - Prevents privilege escalation via stale cached tiers
 *
 * @param workspaceId - The workspace ID to resolve
 * @returns Tier resolution result with tier and optional user info
 *
 * @example
 * ```ts
 * const result = await resolveTierByWorkspaceId("ws_a1b2c3d4...");
 * if (result.found) {
 *   logger.debug(...);
 * } else {
 *   logger.debug(...);
 * }
 * ```
 */
export async function resolveTierByWorkspaceId(workspaceId) {
    if (!db) {
        // Database not available - return free tier as fallback
        return { found: false, tier: "free" };
    }
    try {
        // Validate workspace ID format
        const validatedId = workspaceIdSchema.parse(workspaceId);
        const link = await db.query.workspaceLinks.findFirst({
            // biome-ignore lint/suspicious/noExplicitAny: Drizzle query builder callback
            where: (link, { eq }) => eq(link.workspaceId, validatedId),
        });
        if (!link) {
            return { found: false, tier: "free" };
        }
        // P0 Security: Check link expiration
        if (link.expiresAt && link.expiresAt < new Date()) {
            // Auto-delete expired link
            await db.delete(workspaceLinks).where(eq(workspaceLinks.workspaceId, validatedId));
            process.stdout.write(`[Workspace Links] Deleted expired link: ${validatedId.slice(0, 10)}...`);
            return { found: false, tier: "free" };
        }
        // P0 Security: Check tier staleness (refresh if >24h old)
        const staleCutoff = new Date(Date.now() - TIER_STALENESS_THRESHOLD_MS);
        const tierRefreshedAt = link.tierRefreshedAt ?? link.createdAt; // Fallback for migration
        let tierRefreshed = false;
        let currentTier = link.tier;
        if (tierRefreshedAt < staleCutoff) {
            // Tier is stale - fetch fresh from subscriptions table
            const [subscription] = await db
                .select({ plan: subscriptions.plan })
                .from(subscriptions)
                .where(eq(subscriptions.userId, link.userId))
                .limit(1);
            // Map subscription plan to workspace tier
            const freshTier = mapPlanToTier(subscription?.plan);
            // Update tier and tierRefreshedAt atomically
            await db
                .update(workspaceLinks)
                .set({
                tier: freshTier,
                tierRefreshedAt: new Date(),
                lastSeenAt: new Date(),
            })
                .where(eq(workspaceLinks.workspaceId, validatedId));
            currentTier = freshTier;
            tierRefreshed = true;
            process.stdout.write(`[Workspace Links] Refreshed stale tier for ${validatedId.slice(0, 10)}...: ${link.tier} -> ${freshTier}`);
        }
        else {
            // Update last seen timestamp (fire and forget)
            db.update(workspaceLinks)
                .set({ lastSeenAt: new Date() })
                .where(eq(workspaceLinks.workspaceId, validatedId))
                .catch(() => {
                // Ignore update errors - don't block tier resolution
            });
        }
        return {
            found: true,
            tier: currentTier,
            userId: link.userId,
            displayName: link.displayName ?? undefined,
            tierRefreshed,
        };
    }
    catch (_error) {
        // On any error (validation, db), return free tier
        return { found: false, tier: "free" };
    }
}
/**
 * Map subscription plan to workspace tier
 * Handles the plan_type enum values from subscriptions table
 */
function mapPlanToTier(plan) {
    switch (plan) {
        case "pro":
        case "solo": // Legacy name
            return "pro";
        case "team":
        case "enterprise":
            return "enterprise";
        default:
            return "free";
    }
}
/**
 * Link a workspace to a user
 *
 * Called after successful OAuth authentication in VS Code extension.
 * Uses upsert semantics - updates tier if workspace already linked.
 *
 * P0 Security: expiresAt defaults to 90 days from now
 *
 * @param params - Link parameters
 * @returns The created/updated workspace link
 *
 * @example
 * ```ts
 * // After OAuth success
 * const link = await linkWorkspace({
 *   workspaceId: "ws_a1b2c3d4...",
 *   userId: "user_abc123",
 *   tier: "pro",
 *   displayName: "My MacBook"
 * });
 * ```
 */
export async function linkWorkspace(params) {
    if (!db) {
        throw new Error("Database not available");
    }
    // Validate input
    const validated = linkWorkspaceSchema.parse(params);
    // P0 Security: Default expiration to 90 days
    const expiresAt = validated.expiresAt ?? new Date(Date.now() + WORKSPACE_LINK_TTL_MS);
    // Check if workspace already linked
    const existing = await getWorkspaceLinkById(validated.workspaceId);
    if (existing) {
        // Update existing link
        await db
            .update(workspaceLinks)
            .set({
            userId: validated.userId,
            tier: validated.tier,
            displayName: validated.displayName,
            lastSeenAt: new Date(),
            tierRefreshedAt: new Date(), // Reset staleness on update
            expiresAt, // Extend expiration on update
        })
            .where(eq(workspaceLinks.workspaceId, validated.workspaceId));
        return await getWorkspaceLinkById(validated.workspaceId);
    }
    // Create new link
    await db.insert(workspaceLinks).values({
        workspaceId: validated.workspaceId,
        userId: validated.userId,
        tier: validated.tier,
        displayName: validated.displayName,
        tierRefreshedAt: new Date(),
        expiresAt,
    });
    return await getWorkspaceLinkById(validated.workspaceId);
}
/**
 * Update workspace tier
 *
 * Called when user's subscription changes.
 *
 * @param params - Update parameters
 * @returns True if updated, false if workspace not found
 */
export async function updateWorkspaceTier(params) {
    if (!db) {
        throw new Error("Database not available");
    }
    // Validate input
    const validated = updateTierSchema.parse(params);
    const result = await db
        .update(workspaceLinks)
        .set({
        tier: validated.tier,
        lastSeenAt: new Date(),
    })
        .where(eq(workspaceLinks.workspaceId, validated.workspaceId))
        .returning({ workspaceId: workspaceLinks.workspaceId });
    return result.length > 0;
}
/**
 * Unlink a workspace
 *
 * Called when user signs out or wants to deauthorize a device.
 *
 * @param workspaceId - The workspace ID to unlink
 * @returns True if deleted, false if not found
 */
export async function unlinkWorkspace(workspaceId) {
    if (!db) {
        throw new Error("Database not available");
    }
    // Validate workspace ID format
    const validatedId = workspaceIdSchema.parse(workspaceId);
    const result = await db
        .delete(workspaceLinks)
        .where(eq(workspaceLinks.workspaceId, validatedId))
        .returning({ workspaceId: workspaceLinks.workspaceId });
    return result.length > 0;
}
/**
 * Get all workspace links for a user
 *
 * Useful for displaying linked devices in user settings.
 *
 * @param userId - The user ID to look up
 * @returns Array of workspace links for the user
 */
export async function getWorkspaceLinksByUserId(userId) {
    if (!db) {
        throw new Error("Database not available");
    }
    return await db.query.workspaceLinks.findMany({
        // biome-ignore lint/suspicious/noExplicitAny: Drizzle query builder callbacks
        where: (link, { eq }) => eq(link.userId, userId),
        orderBy: (link, { desc }) => desc(link.lastSeenAt),
    });
}
/**
 * Unlink all workspaces for a user
 *
 * Called when user account is deleted (CASCADE should handle this,
 * but explicit function for manual cleanup).
 *
 * @param userId - The user ID to unlink all workspaces for
 * @returns Number of workspaces unlinked
 */
export async function unlinkAllWorkspacesForUser(userId) {
    if (!db) {
        throw new Error("Database not available");
    }
    const result = await db
        .delete(workspaceLinks)
        .where(eq(workspaceLinks.userId, userId))
        .returning({ workspaceId: workspaceLinks.workspaceId });
    return result.length;
}
