// ESM imports fixed for Node.js v22+
/**
 * Attribution Service Implementation (Gap 4 - High Priority)
 *
 * Handles marketing attribution transfer from web to platform,
 * deduplication, and conversion tracking with database persistence.
 *
 * @module attribution-service
 */
import { shouldMergeAttribution } from "@vreko/contracts";
import { and, eq, gte, lte } from "drizzle-orm";
import { db } from "../db/client.js";
import { userAttributions } from "../db/schema/vreko/user-attributions.js";
/**
 * Attribution Service implementation
 */
export class AttributionServiceImpl {
    // In-memory storage (stub - will be replaced with database)
    attributions = new Map();
    fingerprintIndex = new Map(); // fingerprint -> userId
    /**
     * Transfer attribution from web to platform
     */
    async transferAttribution(request) {
        const { userId, fingerprint, attribution } = request;
        if (!db) {
            // Graceful degradation: use in-memory storage
            return this.transferAttributionInMemory(request);
        }
        try {
            // Check if this fingerprint already has attribution
            const [existingByFingerprint] = await db
                .select()
                .from(userAttributions)
                .where(eq(userAttributions.fingerprint, fingerprint))
                .limit(1);
            if (existingByFingerprint) {
                // Check if we should merge or ignore
                const shouldMerge = shouldMergeAttribution({
                    attributionId: existingByFingerprint.id,
                    source: existingByFingerprint.source,
                    createdAt: existingByFingerprint.createdAt.toISOString(),
                    campaignId: existingByFingerprint.campaignId || undefined,
                }, attribution);
                if (shouldMerge) {
                    // Update existing attribution with new data
                    await db
                        .update(userAttributions)
                        .set({
                        utmParams: {
                            ...existingByFingerprint.utmParams,
                            ...attribution.utmParams,
                        },
                        conversionData: {
                            ...existingByFingerprint.conversionData,
                            ...attribution.conversionData,
                        },
                    })
                        .where(eq(userAttributions.id, existingByFingerprint.id));
                    process.stdout.write(`[Attribution] Merged attribution for user ${userId} (fingerprint: ${fingerprint})`);
                    return {
                        success: true,
                        attributionId: existingByFingerprint.id,
                        action: "merged",
                        existingAttribution: {
                            attributionId: existingByFingerprint.id,
                            source: existingByFingerprint.source,
                            createdAt: existingByFingerprint.createdAt.toISOString(),
                            campaignId: existingByFingerprint.campaignId || undefined,
                        },
                        message: "Attribution updated with new touch point",
                    };
                }
                // Ignore if same fingerprint but different campaign
                process.stdout.write(`[Attribution] Ignored duplicate attribution for user ${userId}`);
                return {
                    success: true,
                    attributionId: existingByFingerprint.id,
                    action: "ignored",
                    existingAttribution: {
                        attributionId: existingByFingerprint.id,
                        source: existingByFingerprint.source,
                        createdAt: existingByFingerprint.createdAt.toISOString(),
                        campaignId: existingByFingerprint.campaignId || undefined,
                    },
                    message: "Attribution already exists for this fingerprint",
                };
            }
            // Check if user already has attribution (race condition protection)
            const [existingByUser] = await db
                .select()
                .from(userAttributions)
                .where(eq(userAttributions.userId, userId))
                .limit(1);
            if (existingByUser) {
                // User already has attribution, return existing
                return {
                    success: true,
                    attributionId: existingByUser.id,
                    action: "ignored",
                    existingAttribution: {
                        attributionId: existingByUser.id,
                        source: existingByUser.source,
                        createdAt: existingByUser.createdAt.toISOString(),
                        campaignId: existingByUser.campaignId || undefined,
                    },
                    message: "User already has attribution",
                };
            }
            // Create new attribution record
            const [newAttribution] = await db
                .insert(userAttributions)
                .values({
                userId,
                source: attribution.source,
                campaignId: attribution.campaignId,
                fingerprint,
                conversionData: attribution.conversionData,
                utmParams: attribution.utmParams,
                referralCode: attribution.referralCode,
                createdAt: new Date(),
            })
                .returning();
            if (!newAttribution) {
                throw new Error("Failed to create attribution record");
            }
            process.stdout.write(`[Attribution] Created new attribution for user ${userId} - Source: ${attribution.source}`);
            return {
                success: true,
                attributionId: newAttribution.id,
                action: "created",
                message: "Attribution recorded successfully",
            };
        }
        catch (_error) {
            // Fall back to in-memory
            return this.transferAttributionInMemory(request);
        }
    }
    /**
     * Get attribution for a user
     */
    async getAttribution(userId) {
        if (!db) {
            return this.attributions.get(userId) || null;
        }
        try {
            const [attribution] = await db
                .select()
                .from(userAttributions)
                .where(eq(userAttributions.userId, userId))
                .limit(1);
            if (!attribution) {
                return null;
            }
            return {
                id: attribution.id,
                userId: attribution.userId,
                source: attribution.source,
                campaignId: attribution.campaignId || undefined,
                fingerprint: attribution.fingerprint,
                conversionData: attribution.conversionData,
                utmParams: attribution.utmParams,
                createdAt: attribution.createdAt,
                referralCode: attribution.referralCode || undefined,
                convertedAt: attribution.convertedAt || undefined,
            };
        }
        catch (_error) {
            return this.attributions.get(userId) || null;
        }
    }
    /**
     * Mark user as converted (purchased subscription)
     */
    async markConverted(userId) {
        if (!db) {
            const attribution = this.attributions.get(userId);
            if (!attribution) {
                return false;
            }
            attribution.convertedAt = new Date();
            process.stdout.write(`[Attribution] Marked user ${userId} as converted - Source: ${attribution.source}`);
            return true;
        }
        try {
            const result = await db
                .update(userAttributions)
                .set({ convertedAt: new Date() })
                .where(eq(userAttributions.userId, userId))
                .returning();
            const updated = result[0];
            if (!updated) {
                return false;
            }
            process.stdout.write(`[Attribution] Marked user ${userId} as converted - Source: ${updated.source}`);
            return true;
        }
        catch (_error) {
            return false;
        }
    }
    /**
     * Get conversion metrics by source
     */
    async getConversionMetrics(dateRange) {
        if (!db) {
            // Fallback to in-memory calculation
            return this.getConversionMetricsInMemory(dateRange);
        }
        try {
            // Build query with date range filter
            let query = db.select().from(userAttributions);
            if (dateRange) {
                query = query.where(and(gte(userAttributions.createdAt, dateRange.from), lte(userAttributions.createdAt, dateRange.to)));
            }
            const attributions = await query;
            // Group by source and calculate metrics
            const metricsBySource = new Map();
            for (const record of attributions) {
                const metrics = metricsBySource.get(record.source) || {
                    total: 0,
                    conversions: 0,
                    timesToConvert: [],
                };
                metrics.total++;
                if (record.convertedAt) {
                    metrics.conversions++;
                    const daysToConvert = (record.convertedAt.getTime() - record.createdAt.getTime()) / (1000 * 60 * 60 * 24);
                    metrics.timesToConvert.push(daysToConvert);
                }
                metricsBySource.set(record.source, metrics);
            }
            // Convert to ConversionMetrics array
            const results = [];
            for (const [source, data] of metricsBySource.entries()) {
                const avgTimeToConvert = data.timesToConvert.length > 0
                    ? data.timesToConvert.reduce((a, b) => a + b, 0) / data.timesToConvert.length
                    : undefined;
                results.push({
                    source: source,
                    totalUsers: data.total,
                    conversions: data.conversions,
                    conversionRate: data.conversions / data.total,
                    avgTimeToConvert,
                });
            }
            return results.sort((a, b) => b.totalUsers - a.totalUsers);
        }
        catch (_error) {
            // Fall back to in-memory
            return this.getConversionMetricsInMemory(dateRange);
        }
    }
    /**
     * Fallback: Transfer attribution in-memory
     */
    transferAttributionInMemory(request) {
        const { userId, fingerprint, attribution } = request;
        // Check if this fingerprint already has attribution
        const existingUserId = this.fingerprintIndex.get(fingerprint);
        if (existingUserId) {
            const existing = this.attributions.get(existingUserId);
            if (existing) {
                // Check if we should merge or ignore
                const shouldMerge = shouldMergeAttribution({
                    attributionId: existing.id,
                    source: existing.source,
                    createdAt: existing.createdAt.toISOString(),
                    campaignId: existing.campaignId,
                }, attribution);
                if (shouldMerge) {
                    existing.utmParams = {
                        ...existing.utmParams,
                        ...attribution.utmParams,
                    };
                    existing.conversionData = {
                        ...existing.conversionData,
                        ...attribution.conversionData,
                    };
                    return {
                        success: true,
                        attributionId: existing.id,
                        action: "merged",
                        existingAttribution: {
                            attributionId: existing.id,
                            source: existing.source,
                            createdAt: existing.createdAt.toISOString(),
                            campaignId: existing.campaignId,
                        },
                        message: "Attribution updated with new touch point",
                    };
                }
                return {
                    success: true,
                    attributionId: existing.id,
                    action: "ignored",
                    existingAttribution: {
                        attributionId: existing.id,
                        source: existing.source,
                        createdAt: existing.createdAt.toISOString(),
                        campaignId: existing.campaignId,
                    },
                    message: "Attribution already exists for this fingerprint",
                };
            }
        }
        // Create new attribution record
        const attributionId = `attr_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        const record = {
            id: attributionId,
            userId,
            source: attribution.source,
            campaignId: attribution.campaignId,
            fingerprint,
            conversionData: attribution.conversionData,
            utmParams: attribution.utmParams,
            createdAt: new Date(),
            referralCode: attribution.referralCode,
        };
        this.attributions.set(userId, record);
        this.fingerprintIndex.set(fingerprint, userId);
        return {
            success: true,
            attributionId,
            action: "created",
            message: "Attribution recorded successfully",
        };
    }
    /**
     * Fallback: Get conversion metrics in-memory
     */
    getConversionMetricsInMemory(dateRange) {
        const metricsBySource = new Map();
        for (const record of this.attributions.values()) {
            if (dateRange) {
                if (record.createdAt < dateRange.from || record.createdAt > dateRange.to) {
                    continue;
                }
            }
            const metrics = metricsBySource.get(record.source) || {
                total: 0,
                conversions: 0,
                timesToConvert: [],
            };
            metrics.total++;
            if (record.convertedAt) {
                metrics.conversions++;
                const daysToConvert = (record.convertedAt.getTime() - record.createdAt.getTime()) / (1000 * 60 * 60 * 24);
                metrics.timesToConvert.push(daysToConvert);
            }
            metricsBySource.set(record.source, metrics);
        }
        // Convert to ConversionMetrics array
        const results = [];
        for (const [source, data] of metricsBySource.entries()) {
            const avgTimeToConvert = data.timesToConvert.length > 0
                ? data.timesToConvert.reduce((a, b) => a + b, 0) / data.timesToConvert.length
                : undefined;
            results.push({
                source: source,
                totalUsers: data.total,
                conversions: data.conversions,
                conversionRate: data.conversions / data.total,
                avgTimeToConvert,
            });
        }
        return results.sort((a, b) => b.totalUsers - a.totalUsers);
    }
}
/**
 * Singleton instance
 */
export const attributionService = new AttributionServiceImpl();
