// ESM imports fixed for Node.js v22+
/**
 * ============================================================================
 * P0-1: Vector Similarity Search Queries
 * ============================================================================
 * Purpose: Type-safe vector similarity search for patterns table
 * Requires: pgvector extension enabled (Migration 0011)
 * ============================================================================
 */
import { sql } from "drizzle-orm";
import { db } from "../client.js";
import { patterns } from "../schema/vreko/patterns.js";
/**
 * Search for similar patterns using cosine similarity
 *
 * @param queryVector - 256-dimensional embedding vector
 * @param limit - Maximum results to return (default: 10)
 * @param similarityThreshold - Minimum similarity score (0-1, default: 0.75)
 * @param patternType - Optional filter by pattern type
 * @param isGlobal - Optional filter by global/local patterns
 * @returns Array of similar patterns with similarity scores
 *
 * @example
 * const results = await searchSimilarPatterns(
 *   [0.1, 0.2, ...], // 256 dimensions
 *   5,
 *   0.8,
 *   'dangerous'
 * );
 */
export async function searchSimilarPatterns(queryVector, limit = 10, similarityThreshold = 0.75, patternType, isGlobal) {
    // Validate vector dimensions
    if (queryVector.length !== 256) {
        throw new Error(`Expected 256-dimensional vector, got ${queryVector.length}`);
    }
    // Convert vector to SQL format
    const vectorLiteral = `[${queryVector.join(",")}]`;
    // Build query with optional filters
    let query = db
        .select({
        id: patterns.id,
        patternSignature: patterns.patternSignature,
        patternType: patterns.patternType,
        // Cosine similarity: 1 - distance (higher is more similar)
        similarity: sql `1 - (${patterns.embedding} <=> ${vectorLiteral}::vector)`,
        occurrenceCount: patterns.occurrenceCount,
        successRate: patterns.successRate,
        isGlobal: patterns.isGlobal,
    })
        .from(patterns)
        .where(sql `1 - (${patterns.embedding} <=> ${vectorLiteral}::vector) >= ${similarityThreshold}`);
    // Apply optional filters
    if (patternType) {
        query = query.where(sql `${patterns.patternType} = ${patternType}`);
    }
    if (isGlobal !== undefined) {
        query = query.where(sql `${patterns.isGlobal} = ${isGlobal}`);
    }
    // Order by similarity (closest first) and limit results
    const results = await query.orderBy(sql `${patterns.embedding} <=> ${vectorLiteral}::vector`).limit(limit);
    return results;
}
/**
 * Find patterns similar to a given pattern ID
 *
 * @param patternId - ID of the reference pattern
 * @param limit - Maximum results to return (default: 5)
 * @param excludeSelf - Whether to exclude the reference pattern (default: true)
 * @returns Array of similar patterns
 */
export async function findSimilarPatterns(patternId, limit = 5, excludeSelf = true) {
    // Get the embedding of the reference pattern
    const referencePattern = await db
        .select({ embedding: patterns.embedding })
        .from(patterns)
        .where(sql `${patterns.id} = ${patternId}`)
        .limit(1);
    if (!referencePattern.length || !referencePattern[0].embedding) {
        throw new Error(`Pattern ${patternId} not found or has no embedding`);
    }
    const queryVector = referencePattern[0].embedding;
    const vectorLiteral = `[${queryVector.join(",")}]`;
    // Find similar patterns
    let query = db
        .select({
        id: patterns.id,
        patternSignature: patterns.patternSignature,
        patternType: patterns.patternType,
        similarity: sql `1 - (${patterns.embedding} <=> ${vectorLiteral}::vector)`,
        occurrenceCount: patterns.occurrenceCount,
        successRate: patterns.successRate,
        isGlobal: patterns.isGlobal,
    })
        .from(patterns)
        .where(sql `${patterns.embedding} IS NOT NULL`);
    if (excludeSelf) {
        query = query.where(sql `${patterns.id} != ${patternId}`);
    }
    const results = await query.orderBy(sql `${patterns.embedding} <=> ${vectorLiteral}::vector`).limit(limit);
    return results;
}
/**
 * Insert a new pattern with embedding
 *
 * @param patternSignature - Unique pattern signature (AST hash)
 * @param embedding - 256-dimensional vector embedding
 * @param patternType - Pattern classification
 * @param userId - Optional user ID (null for global patterns)
 * @param toolAffinity - Optional tool affinity array
 * @param fileTypes - Optional file type array
 * @returns The created pattern ID
 */
export async function insertPatternWithEmbedding(patternSignature, embedding, patternType, userId, toolAffinity, fileTypes) {
    // Validate vector dimensions
    if (embedding.length !== 256) {
        throw new Error(`Expected 256-dimensional vector, got ${embedding.length}`);
    }
    const result = await db
        .insert(patterns)
        .values({
        patternSignature,
        embedding,
        patternType,
        userId,
        toolAffinity: toolAffinity ?? [],
        fileTypes: fileTypes ?? [],
        isGlobal: !userId,
    })
        .returning({ id: patterns.id });
    return result[0].id;
}
/**
 * Update pattern embedding
 *
 * @param patternId - Pattern ID to update
 * @param embedding - New 256-dimensional vector embedding
 */
export async function updatePatternEmbedding(patternId, embedding) {
    // Validate vector dimensions
    if (embedding.length !== 256) {
        throw new Error(`Expected 256-dimensional vector, got ${embedding.length}`);
    }
    await db.update(patterns).set({ embedding }).where(sql `${patterns.id} = ${patternId}`);
}
/**
 * Test if pgvector extension is available
 *
 * @returns true if pgvector is enabled
 */
export async function isPgvectorEnabled() {
    try {
        const result = await db.execute(sql `
			SELECT 1 FROM pg_extension WHERE extname = 'vector'
		`);
        return result.rows.length > 0;
    }
    catch {
        return false;
    }
}
/**
 * Get vector search statistics
 *
 * @returns Statistics about the patterns table and vector index
 */
export async function getVectorStats() {
    const [totalResult, embeddingResult, indexResult] = await Promise.all([
        db.select({ count: sql `count(*)` }).from(patterns),
        db.select({ count: sql `count(*)` }).from(patterns).where(sql `${patterns.embedding} IS NOT NULL`),
        db.execute(sql `
			SELECT indexname, indexdef
			FROM pg_indexes
			WHERE tablename = 'patterns'
			AND indexdef LIKE '%hnsw%'
		`),
    ]);
    const indexRow = indexResult.rows[0];
    return {
        totalPatterns: totalResult[0]?.count ?? 0,
        patternsWithEmbeddings: embeddingResult[0]?.count ?? 0,
        indexName: indexRow?.indexname ?? null,
        indexType: indexRow?.indexdef?.includes("hnsw") ? "hnsw" : null,
    };
}
