import { randomBytes } from "node:crypto";
/**
 * Saga Orchestrator Implementation
 *
 * Implements saga pattern for multi-step workflows with:
 * - Step-by-step execution with compensation on failure
 * - Persistence for recovery after crashes
 * - Retry logic for transient failures
 * - Event emission for monitoring
 *
 * Architecture:
 * - Orchestration-based (centralized coordinator)
 * - Forward recovery with compensation
 * - Persistent state for crash recovery
 * - Timeout handling per step
 */
export class SagaOrchestratorImpl {
    persistence;
    definitions = new Map();
    runningInstances = new Map();
    constructor(persistence) {
        this.persistence = persistence;
        /* intentionally empty */
    }
    /**
     * Register a saga definition
     */
    registerSaga(definition) {
        this.definitions.set(definition.sagaType, definition);
        process.stdout.write(`[SagaOrchestrator] Registered saga type: ${definition.sagaType}`);
    }
    /**
     * Start a new saga instance
     */
    async start(sagaType, initialContext) {
        const definition = this.definitions.get(sagaType);
        if (!definition) {
            throw new Error(`Saga type not registered: ${sagaType}`);
        }
        // Create saga instance
        const sagaId = this.generateSagaId();
        const instance = {
            sagaId,
            sagaType,
            status: "pending",
            context: initialContext,
            steps: definition.steps.map((step) => ({
                stepId: step.stepId,
                stepName: step.stepName,
                status: "pending",
                input: {},
                output: null,
                error: null,
                startedAt: null,
                completedAt: null,
                compensatedAt: null,
            })),
            startedAt: new Date(),
            completedAt: null,
            failedAt: null,
            error: null,
            retryCount: 0,
            maxRetries: definition.maxRetries || 3,
        };
        // Persist initial state
        await this.persistence.save(instance);
        // Store in memory
        this.runningInstances.set(sagaId, instance);
        // Start execution asynchronously
        this.executeAsync(sagaId, definition);
        return instance;
    }
    /**
     * Resume a saga from persisted state
     */
    async resume(sagaId) {
        // Load from persistence
        const instance = await this.persistence.load(sagaId);
        if (!instance) {
            throw new Error(`Saga not found: ${sagaId}`);
        }
        // Get definition
        const definition = this.definitions.get(instance.sagaType);
        if (!definition) {
            throw new Error(`Saga type not registered: ${instance.sagaType}`);
        }
        // Store in memory
        this.runningInstances.set(sagaId, instance);
        // Resume execution
        this.executeAsync(sagaId, definition);
        return instance;
    }
    /**
     * Get saga status
     */
    async getStatus(sagaId) {
        // Check in-memory first
        const running = this.runningInstances.get(sagaId);
        if (running) {
            return running;
        }
        // Load from persistence
        return this.persistence.load(sagaId);
    }
    /**
     * List all sagas
     */
    async listSagas(filter) {
        return this.persistence.listAll(filter);
    }
    /**
     * Execute saga steps asynchronously
     */
    async executeAsync(sagaId, definition) {
        const instance = this.runningInstances.get(sagaId);
        if (!instance) {
            return;
        }
        try {
            // Update status to running
            instance.status = "running";
            await this.persistence.update(sagaId, { status: "running" });
            // Execute steps in order
            for (let i = 0; i < definition.steps.length; i++) {
                const stepDef = definition.steps[i];
                const stepExec = instance.steps[i];
                if (!stepDef || !stepExec) {
                    throw new Error(`Step definition or execution not found at index ${i}`);
                }
                // Skip if already completed
                if (stepExec.status === "completed") {
                    continue;
                }
                // Execute step
                const success = await this.executeStep(instance, stepDef, stepExec);
                if (!success) {
                    // Step failed - start compensation
                    await this.compensate(instance, definition, i);
                    return;
                }
                // Persist progress
                if (definition.persistenceInterval) {
                    await this.persistence.update(sagaId, { steps: instance.steps });
                }
            }
            // All steps completed
            instance.status = "completed";
            instance.completedAt = new Date();
            await this.persistence.update(sagaId, {
                status: "completed",
                completedAt: instance.completedAt,
            });
            process.stdout.write(`[SagaOrchestrator] Saga completed: ${sagaId}`);
        }
        catch (error) {
            instance.status = "failed";
            instance.failedAt = new Date();
            instance.error = error instanceof Error ? error.message : String(error);
            await this.persistence.update(sagaId, {
                status: "failed",
                failedAt: instance.failedAt,
                error: instance.error,
            });
        }
        finally {
            // Remove from running instances
            this.runningInstances.delete(sagaId);
        }
    }
    /**
     * Execute a single saga step
     */
    async executeStep(instance, stepDef, stepExec) {
        stepExec.status = "running";
        stepExec.startedAt = new Date();
        try {
            // Execute with timeout
            const timeoutMs = stepDef.timeout || 30000;
            const result = await this.executeWithTimeout(stepDef.execute(stepExec.input, instance.context), timeoutMs);
            // Store output
            stepExec.output = result;
            stepExec.status = "completed";
            stepExec.completedAt = new Date();
            process.stdout.write(`[SagaOrchestrator] Step completed: ${stepDef.stepId}`);
            return true;
        }
        catch (error) {
            // Handle step failure
            stepExec.error = error instanceof Error ? error.message : String(error);
            stepExec.status = "failed";
            // Retry if retryable and retries remaining
            if (stepDef.retryable && instance.retryCount < instance.maxRetries) {
                instance.retryCount++;
                process.stdout.write(`[SagaOrchestrator] Retrying step ${stepDef.stepId} (${instance.retryCount}/${instance.maxRetries})`);
                // Reset step status for retry
                stepExec.status = "pending";
                stepExec.error = null;
                // Wait before retry (exponential backoff)
                const delayMs = Math.min(1000 * 2 ** instance.retryCount, 30000);
                await this.sleep(delayMs);
                // Retry
                return this.executeStep(instance, stepDef, stepExec);
            }
            return false;
        }
    }
    /**
     * Compensate (rollback) completed steps
     */
    async compensate(instance, definition, failedStepIndex) {
        instance.status = "compensating";
        await this.persistence.update(instance.sagaId, { status: "compensating" });
        process.stdout.write(`[SagaOrchestrator] Starting compensation for saga: ${instance.sagaId}`);
        // Compensate completed steps in reverse order
        for (let i = failedStepIndex - 1; i >= 0; i--) {
            const stepDef = definition.steps[i];
            const stepExec = instance.steps[i];
            if (!stepDef || !stepExec) {
                continue;
            }
            // Skip if not completed
            if (stepExec.status !== "completed") {
                continue;
            }
            // Skip if no compensation function
            if (!stepDef.compensate) {
                process.stdout.write(`[SagaOrchestrator] No compensation for step: ${stepDef.stepId}`);
                continue;
            }
            try {
                await stepDef.compensate(stepExec.input, stepExec.output, instance.context);
                stepExec.status = "compensated";
                stepExec.compensatedAt = new Date();
                process.stdout.write(`[SagaOrchestrator] Compensated step: ${stepDef.stepId}`);
            }
            catch (_error) {
                // Continue compensating other steps even if one fails
            }
        }
        instance.status = "compensated";
        instance.failedAt = new Date();
        await this.persistence.update(instance.sagaId, {
            status: "compensated",
            failedAt: instance.failedAt,
            steps: instance.steps,
        });
        process.stdout.write(`[SagaOrchestrator] Compensation completed for saga: ${instance.sagaId}`);
    }
    // Helper methods
    generateSagaId() {
        return `saga_${randomBytes(16).toString("hex")}`;
    }
    async executeWithTimeout(promise, timeoutMs) {
        return Promise.race([
            promise,
            new Promise((_resolve, reject) => setTimeout(() => reject(new Error("Step execution timeout")), timeoutMs)),
        ]);
    }
    sleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }
}
