import { createLogger, LogLevel } from "@vreko/contracts";
import { PostHog } from "posthog-node";

// =============================================================================
// Feature Flag Name Constants
// PostHog feature flag keys  -  use VREKO_* for new flags; SNAPBACK_* are kept
// as deprecated fallbacks for the 90-day migration window.
// Consumer usage pattern:
//   const enabled = await isFeatureEnabled(VREKO_ENABLE_LEARNING, userId)
//     ?? await isFeatureEnabled(SNAPBACK_ENABLE_LEARNING, userId); // fallback
// =============================================================================

export const VREKO_ENABLE_LEARNING = "vreko-enable-learning";
/** @deprecated Use VREKO_ENABLE_LEARNING instead */
export const SNAPBACK_ENABLE_LEARNING = "snapback-enable-learning";

export const VREKO_ENABLE_INTELLIGENCE = "vreko-enable-intelligence";
/** @deprecated Use VREKO_ENABLE_INTELLIGENCE instead */
export const SNAPBACK_ENABLE_INTELLIGENCE = "snapback-enable-intelligence";

export const VREKO_ENABLE_MCP = "vreko-enable-mcp";
/** @deprecated Use VREKO_ENABLE_MCP instead */
export const SNAPBACK_ENABLE_MCP = "snapback-enable-mcp";

export const VREKO_ENABLE_PIONEER_FEATURES = "vreko-enable-pioneer-features";
/** @deprecated Use VREKO_ENABLE_PIONEER_FEATURES instead */
export const SNAPBACK_ENABLE_PIONEER_FEATURES = "snapback-enable-pioneer-features";

export const VREKO_ENABLE_BETA_UI = "vreko-enable-beta-ui";
/** @deprecated Use VREKO_ENABLE_BETA_UI instead */
export const SNAPBACK_ENABLE_BETA_UI = "snapback-enable-beta-ui";

const logger = createLogger({ name: "feature-flags", level: LogLevel.INFO });

// Initialize PostHog for feature flags
const posthog = new PostHog(process.env.POSTHOG_API_KEY || "default_key", {
	host: process.env.POSTHOG_HOST || "https://app.posthog.com",
});

// Check if a feature flag is enabled for a user
export async function isFeatureEnabled(
	flag: string,
	userId: string,
	properties: Record<string, unknown> = {},
): Promise<boolean> {
	try {
		const result = await posthog.isFeatureEnabled(flag, userId, properties);
		return result ?? false;
	} catch (error) {
		// If there's an error checking feature flags, we'll be conservative and disable the feature
		logger.error("Error checking feature flag:", { error });
		return false;
	}
}

// Get the value of a feature flag for a user
export async function getFeatureFlag(
	flag: string,
	userId: string,
	properties: Record<string, unknown> = {},
): Promise<string | boolean | number | undefined> {
	try {
		const result = await posthog.getFeatureFlag(flag, userId, properties);
		return result ?? undefined;
	} catch (error) {
		// If there's an error getting feature flag value, return undefined
		logger.error("Error getting feature flag value:", { error });
		return undefined;
	}
}

// Track feature flag usage
export async function trackFeatureFlag(
	flag: string,
	userId: string,
	properties: Record<string, unknown> = {},
): Promise<void> {
	try {
		posthog.capture({
			distinctId: userId,
			event: "feature_flag_evaluated",
			properties: {
				feature_flag: flag,
				...properties,
			},
		});
	} catch (error) {
		// If there's an error tracking, we'll log it but not fail
		logger.error("Error tracking feature flag:", { error });
	}
}

// Gracefully shutdown PostHog
export async function shutdownFeatureFlags(): Promise<void> {
	try {
		await posthog.shutdownAsync();
	} catch (error) {
		logger.error("Error shutting down PostHog:", { error });
	}
}
