// ESM imports fixed for Node.js v22+
/**
 * MCP Service Layer
 *
 * Handles persistent storage of MCP observations and tool invocations.
 * Provides idempotency, batching, and conflict resolution.
 *
 * @module platform/services
 */
import { and, eq, gte, sql } from "drizzle-orm";
import { db } from "../db/client.js";
import { extensionSyncState, mcpObservations, mcpToolInvocations } from "../db/schema/vreko/mcp.js";
// ============================================================================
// Database Access Helper
// ============================================================================
function getDb() {
    if (!db) {
        throw new Error("Database not initialized. Check DATABASE_URL environment variable.");
    }
    return db;
}
// ============================================================================
// MCP Service
// ============================================================================
export class MCPService {
    /**
     * Record an observation from the MCP bridge
     * Uses idempotency key to prevent duplicates
     */
    async recordObservation(input) {
        const database = getDb();
        // Check idempotency if key provided
        if (input.idempotencyKey) {
            const existing = await database
                .select({ id: mcpObservations.id })
                .from(mcpObservations)
                .where(eq(mcpObservations.idempotencyKey, input.idempotencyKey))
                .limit(1);
            if (existing.length > 0) {
                return { id: existing[0].id, created: false };
            }
        }
        // Insert new observation
        const data = {
            workspaceId: input.workspaceId,
            userId: input.userId,
            type: input.type,
            severity: input.severity,
            message: input.message,
            context: input.context ?? {},
            filePath: input.filePath,
            lineNumber: input.lineNumber,
            source: input.source ?? "extension",
            toolName: input.toolName,
            idempotencyKey: input.idempotencyKey,
            deviceId: input.deviceId,
            observedAt: input.observedAt ?? new Date(),
            processed: false,
        };
        const result = await database.insert(mcpObservations).values(data).returning({ id: mcpObservations.id });
        return { id: result[0].id, created: true };
    }
    /**
     * Record a tool invocation
     * Uses idempotency key to prevent duplicates
     */
    async recordInvocation(input) {
        const database = getDb();
        // Check idempotency if key provided
        if (input.idempotencyKey) {
            const existing = await database
                .select({ id: mcpToolInvocations.id })
                .from(mcpToolInvocations)
                .where(eq(mcpToolInvocations.idempotencyKey, input.idempotencyKey))
                .limit(1);
            if (existing.length > 0) {
                return { id: existing[0].id, created: false };
            }
        }
        // Insert new invocation
        const data = {
            workspaceId: input.workspaceId,
            userId: input.userId,
            toolName: input.toolName,
            toolVersion: input.toolVersion,
            invocationType: input.invocationType,
            requestPayload: input.requestPayload,
            responsePayload: input.responsePayload,
            status: input.status ?? "pending",
            errorMessage: input.errorMessage,
            inputTokens: input.inputTokens ?? 0,
            outputTokens: input.outputTokens ?? 0,
            idempotencyKey: input.idempotencyKey,
            source: input.source ?? "extension",
            sessionId: input.sessionId,
            durationMs: input.durationMs,
        };
        const result = await database.insert(mcpToolInvocations).values(data).returning({ id: mcpToolInvocations.id });
        return { id: result[0].id, created: true };
    }
    /**
     * Update sync state for a device
     * Creates or updates the sync state record
     */
    async updateSyncState(input) {
        const database = getDb();
        // Try to update existing record
        const updateResult = await database
            .update(extensionSyncState)
            .set({
            lastSyncAt: input.lastSyncAt ?? new Date(),
            syncVersion: input.syncVersion ?? sql `${extensionSyncState.syncVersion} + 1`,
            deviceType: input.deviceType,
            deviceName: input.deviceName,
            pendingChangesCount: input.pendingChangesCount ?? 0,
            pendingChanges: input.pendingChanges ?? [],
            isOnline: input.isOnline ?? true,
            lastHeartbeatAt: new Date(),
            updatedAt: new Date(),
        })
            .where(and(eq(extensionSyncState.userId, input.userId), eq(extensionSyncState.workspaceId, input.workspaceId), eq(extensionSyncState.deviceId, input.deviceId)))
            .returning({ id: extensionSyncState.id });
        if (updateResult.length > 0) {
            return { id: updateResult[0].id, created: false };
        }
        // Create new record
        const data = {
            userId: input.userId,
            workspaceId: input.workspaceId,
            deviceId: input.deviceId,
            deviceType: input.deviceType,
            deviceName: input.deviceName,
            lastSyncAt: input.lastSyncAt ?? new Date(),
            syncVersion: input.syncVersion ?? 1,
            pendingChangesCount: input.pendingChangesCount ?? 0,
            pendingChanges: input.pendingChanges ?? [],
            isOnline: input.isOnline ?? true,
            lastHeartbeatAt: new Date(),
        };
        const result = await database.insert(extensionSyncState).values(data).returning({ id: extensionSyncState.id });
        return { id: result[0].id, created: true };
    }
    /**
     * Query observations with filters
     */
    async queryObservations(input) {
        const database = getDb();
        // Build where conditions dynamically
        const conditions = [eq(mcpObservations.workspaceId, input.workspaceId)];
        if (input.userId) {
            conditions.push(eq(mcpObservations.userId, input.userId));
        }
        if (input.processed !== undefined) {
            conditions.push(eq(mcpObservations.processed, input.processed));
        }
        if (input.after) {
            conditions.push(gte(mcpObservations.createdAt, input.after));
        }
        const results = await database
            .select()
            .from(mcpObservations)
            .where(and(...conditions))
            .orderBy(sql `${mcpObservations.createdAt} DESC`)
            .limit(input.limit ?? 100);
        return results;
    }
    /**
     * Mark observations as processed
     */
    async markObservationsProcessed(observationIds) {
        if (observationIds.length === 0) {
            return 0;
        }
        const database = getDb();
        const result = await database
            .update(mcpObservations)
            .set({
            processed: true,
            processedAt: new Date(),
            updatedAt: new Date(),
        })
            .where(sql `${mcpObservations.id} IN (${observationIds.join(",")})`);
        return result.rowCount ?? 0;
    }
}
// ============================================================================
// Singleton Instance
// ============================================================================
let instance = null;
export function getMCPService() {
    if (!instance) {
        instance = new MCPService();
    }
    return instance;
}
