// ESM imports fixed for Node.js v22+
/**
 * Entitlements Service Implementation (Gap 1 - Critical Priority)
 *
 * Provides entitlements resolution with caching, feature access checks,
 * and tier validation. This implementation uses Drizzle ORM for database
 * queries and Redis for caching.
 *
 * @module entitlements-service
 */
import { CREDIT_OVERAGE_SOFT_CAP, TIER_CREDIT_ALLOWANCES } from "@vreko/config";
import { getEffectiveTier, getTierFeatures, getTierLimit, isFeatureAvailableAtTier } from "@vreko/contracts";
import { logger } from "@vreko/infrastructure";
import { and, desc, eq, gt, lte, sum } from "drizzle-orm";
import { deleteCache, getCache, isRedisAvailable, setCache } from "../cache/redis-client.js";
import { db } from "../db/client.js";
import { subscriptions, trials, usageLimits } from "../db/schema/postgres.js";
import { creditsLedger } from "../db/schema/vreko/credits-ledger.js";
import { pioneerRedemptions, pioneers } from "../db/schema/vreko/pioneers.js";
/**
 * Stub implementation of EntitlementsService
 */
export class EntitlementsServiceImpl {
    cache = new Map();
    CACHE_TTL_MS = 60_000; // 60 seconds
    /**
     * Fetch complete entitlement set for a user
     * Queries database for subscription, trial, and Pioneer status with Redis caching
     */
    async getEntitlements(userId) {
        // Check Redis cache first (if available)
        if (isRedisAvailable()) {
            const cached = await getCache(`entitlements:${userId}`);
            if (cached) {
                return cached;
            }
        }
        // Fallback to in-memory cache
        const memoryCached = this.cache.get(userId);
        if (memoryCached && Date.now() - memoryCached.timestamp < this.CACHE_TTL_MS) {
            return memoryCached.entitlements;
        }
        if (!db) {
            // Graceful degradation: return default entitlements if DB unavailable
            const entitlements = this.createDefaultEntitlements(userId);
            return entitlements;
        }
        try {
            // Query user's subscription
            const [subscription] = await db
                .select()
                .from(subscriptions)
                .where(eq(subscriptions.userId, userId))
                .limit(1);
            // Query trial status
            const [trial] = await db
                .select()
                .from(trials)
                .where(and(eq(trials.userId, userId), eq(trials.status, "active")))
                .limit(1);
            // Query Pioneer profile if feature flag is enabled
            // Controlled by FEATURE_PIONEER_PROGRAM env var (default: true)
            const isPioneerEnabled = process.env.FEATURE_PIONEER_PROGRAM !== "false";
            let pioneerData = null;
            if (isPioneerEnabled) {
                try {
                    const [pioneerRow] = await db
                        .select({
                        id: pioneers.id,
                        githubStarred: pioneers.githubStarred,
                        joinedAt: pioneers.joinedAt,
                    })
                        .from(pioneers)
                        .where(eq(pioneers.userId, userId))
                        .limit(1);
                    if (pioneerRow) {
                        // Tier is derived from redemption existence (simplified post-CANON.md)
                        const [redemption] = await db
                            .select({ id: pioneerRedemptions.id })
                            .from(pioneerRedemptions)
                            .where(eq(pioneerRedemptions.userId, userId))
                            .limit(1);
                        pioneerData = {
                            tier: redemption ? "founding_pioneer" : "pioneer",
                            totalPoints: 0, // Points system removed per CANON.md
                        };
                    }
                }
                catch (pioneerError) {
                    // Non-fatal: log and continue without pioneer data
                    // (AP-3: every catch must log)
                    logger.warn("[entitlements] Pioneer query failed, continuing without pioneer data", {
                        userId,
                        error: pioneerError instanceof Error ? pioneerError.message : String(pioneerError),
                    });
                }
            }
            // Determine tier based on subscription (respects VREKO_BYPASS_TIER_RESTRICTIONS)
            const tier = getEffectiveTier(subscription?.plan || "free");
            // ENT-001: Query actual usage limits from database
            // Get the most recent usage record for current billing period
            const [usageData] = subscription
                ? await db
                    .select()
                    .from(usageLimits)
                    .where(eq(usageLimits.subscriptionId, subscription.id))
                    .orderBy(desc(usageLimits.month))
                    .limit(1)
                : [null];
            // Calculate credit balance from ledger (pricing_spec_v3.md)
            const creditBalance = await this.calculateCreditBalance(userId, tier, subscription);
            // Build entitlements with real usage data
            const entitlements = this.buildEntitlements(userId, tier, trial || null, pioneerData, subscription || null, usageData || null, creditBalance);
            // Cache in Redis (60 seconds TTL)
            if (isRedisAvailable()) {
                await setCache(`entitlements:${userId}`, entitlements, 60);
            }
            // Cache in memory as backup
            this.cache.set(userId, {
                entitlements,
                timestamp: Date.now(),
            });
            return entitlements;
        }
        catch (_error) {
            // Return default entitlements on error
            return this.createDefaultEntitlements(userId);
        }
    }
    /**
     * Check if user has access to a specific feature
     */
    async checkFeatureAccess(userId, feature) {
        const entitlements = await this.getEntitlements(userId);
        // Check if feature is in user's feature list
        if (entitlements.features.includes(feature)) {
            // Check usage limits
            const limit = entitlements.limits.get(feature);
            if (limit && limit.max !== null && limit.current >= limit.max) {
                return {
                    granted: false,
                    reason: "usage_limit_reached",
                    limitInfo: limit,
                };
            }
            return { granted: true };
        }
        // Check if trial provides access
        if (entitlements.trial?.active && entitlements.trial.features.includes(feature)) {
            return { granted: true };
        }
        // Check Pioneer tier benefits (Guardian = lifetime Pro)
        if (entitlements.pioneer?.tier === "founding_pioneer") {
            // Guardian tier grants lifetime Pro access
            if (isFeatureAvailableAtTier(feature, "pro")) {
                return { granted: true };
            }
        }
        // Determine required tier for feature
        const requiredTier = this.getRequiredTierForFeature(feature);
        return {
            granted: false,
            reason: "feature_not_in_plan",
            requiredTier,
        };
    }
    /**
     * Get usage limits for a specific feature
     */
    async getFeatureLimits(userId, feature) {
        const entitlements = await this.getEntitlements(userId);
        return entitlements.limits.get(feature) || null;
    }
    /**
     * Check if user meets minimum tier requirement
     */
    async checkTierRequirement(userId, requiredTier) {
        const entitlements = await this.getEntitlements(userId);
        return this.compareTiers(entitlements.tier, requiredTier) >= 0;
    }
    /**
     * Invalidate cached entitlements for a user (both Redis and memory)
     */
    async invalidateCache(userId) {
        this.cache.delete(userId);
        // Invalidate Redis cache
        if (isRedisAvailable()) {
            await deleteCache(`entitlements:${userId}`);
        }
    }
    /**
     * Build entitlements from database query results
     */
    buildEntitlements(userId, tier, trial, pioneer, subscription, usageData, creditBalance) {
        const features = getTierFeatures(tier);
        // Add trial features if active
        const trialInfo = trial
            ? {
                active: true,
                endsAt: trial.endsAt,
                features: trial.features || [],
            }
            : null;
        // Add Pioneer info if enrolled
        const pioneerInfo = pioneer
            ? {
                tier: pioneer.tier,
                totalPoints: pioneer.totalPoints,
                pointsToNext: this.calculatePointsToNext(pioneer.tier, pioneer.totalPoints),
                nextTier: this.getNextTier(pioneer.tier),
                discountPercent: this.getTierDiscount(pioneer.tier),
                benefits: this.getTierBenefits(pioneer.tier),
            }
            : null;
        // Create limits map with real usage data (ENT-001)
        const limits = new Map();
        for (const feature of features) {
            const maxLimit = getTierLimit(tier, feature);
            if (maxLimit !== null) {
                // Map feature to usage data from database
                const current = this.getFeatureUsage(feature, usageData);
                limits.set(feature, {
                    feature,
                    current,
                    max: maxLimit,
                    period: "monthly",
                });
            }
        }
        // Determine effective date and expiry
        const effectiveDate = subscription?.currentPeriodStart || new Date();
        const expiresAt = subscription?.currentPeriodEnd || null;
        return {
            userId,
            tier,
            features,
            limits,
            trial: trialInfo,
            pioneer: pioneerInfo,
            credits: creditBalance,
            effectiveDate,
            expiresAt,
            version: 1,
            reason: "subscription",
        };
    }
    /**
     * Create default entitlements for a user (graceful degradation fallback)
     * Used when database is unavailable - returns free tier with no usage data
     */
    createDefaultEntitlements(userId) {
        const tier = "free"; // Default to free tier
        const features = getTierFeatures(tier);
        // Create limits map with zero usage (safe defaults)
        const limits = new Map();
        for (const feature of features) {
            const maxLimit = getTierLimit(tier, feature);
            if (maxLimit !== null) {
                limits.set(feature, {
                    feature,
                    current: 0, // Safe default when DB unavailable
                    max: maxLimit,
                    period: "monthly",
                });
            }
        }
        // Default credit balance for free tier
        const defaultCredits = {
            included: TIER_CREDIT_ALLOWANCES.free,
            topups: 0,
            total: TIER_CREDIT_ALLOWANCES.free,
            overage: 0,
            softCapReached: false,
            monthlyAllowance: TIER_CREDIT_ALLOWANCES.free,
        };
        return {
            userId,
            tier,
            features,
            limits,
            trial: null, // Trials unavailable in fallback mode
            pioneer: null, // Pioneer status unavailable in fallback mode
            credits: defaultCredits,
            effectiveDate: new Date(),
            expiresAt: null,
            version: 1,
            reason: "subscription",
        };
    }
    /**
     * Calculate credit balance from the credits ledger (pricing_spec_v3.md)
     * Per spec: Balance = included credits + top-up credits - consumption
     */
    async calculateCreditBalance(userId, tier, subscription) {
        const monthlyAllowance = TIER_CREDIT_ALLOWANCES[tier] || 0;
        // Get current billing period
        const now = new Date();
        const billingPeriodStart = subscription?.currentPeriodStart || new Date(now.getFullYear(), now.getMonth(), 1);
        const billingPeriodEnd = subscription?.currentPeriodEnd || new Date(now.getFullYear(), now.getMonth() + 1, 0);
        try {
            // Calculate included credits (monthly allowance granted this period)
            const [includedResult] = await db
                .select({ total: sum(creditsLedger.credits) })
                .from(creditsLedger)
                .where(and(eq(creditsLedger.userId, userId), eq(creditsLedger.transactionType, "monthly_allowance"), gt(creditsLedger.createdAt, billingPeriodStart), lte(creditsLedger.createdAt, billingPeriodEnd)));
            // Calculate top-up credits (all time, they don't expire)
            const [topupResult] = await db
                .select({ total: sum(creditsLedger.credits) })
                .from(creditsLedger)
                .where(and(eq(creditsLedger.userId, userId), eq(creditsLedger.transactionType, "top_up")));
            // Calculate consumption (all time, negative values)
            const [consumptionResult] = await db
                .select({ total: sum(creditsLedger.credits) })
                .from(creditsLedger)
                .where(and(eq(creditsLedger.userId, userId), eq(creditsLedger.transactionType, "job_consumption")));
            const included = Number(includedResult?.total || 0);
            const topups = Number(topupResult?.total || 0);
            const consumption = Number(consumptionResult?.total || 0);
            // Calculate balance: included + topups + consumption (consumption is negative)
            const total = included + topups + consumption;
            const overage = total < 0 ? Math.abs(total) : 0;
            const softCapReached = total <= CREDIT_OVERAGE_SOFT_CAP;
            return {
                included: Math.max(0, included + consumption),
                topups,
                total,
                overage,
                softCapReached,
                monthlyAllowance,
            };
        }
        catch (_error) {
            // Return default balance on error
            return {
                included: monthlyAllowance,
                topups: 0,
                total: monthlyAllowance,
                overage: 0,
                softCapReached: false,
                monthlyAllowance,
            };
        }
    }
    /**
     * Determine required tier for a feature
     */
    getRequiredTierForFeature(feature) {
        const tiers = ["free", "pro", "team", "enterprise"];
        for (const tier of tiers) {
            if (isFeatureAvailableAtTier(feature, tier)) {
                return tier;
            }
        }
        return "enterprise"; // Default to highest tier
    }
    /**
     * Calculate points needed to reach next tier
     */
    calculatePointsToNext(currentTier, totalPoints) {
        const PIONEER_TIER_THRESHOLDS = {
            pioneer: 0,
            active_pioneer: 1,
            contributing_pioneer: 2,
            founding_pioneer: 3,
        };
        const tierOrder = ["pioneer", "active_pioneer", "contributing_pioneer", "founding_pioneer"];
        const currentIndex = tierOrder.indexOf(currentTier);
        if (currentIndex === -1 || currentIndex === tierOrder.length - 1) {
            return 0; // Already at max tier
        }
        const nextTier = tierOrder[currentIndex + 1];
        if (!nextTier) {
            return 0;
        }
        const threshold = PIONEER_TIER_THRESHOLDS[nextTier];
        return threshold !== undefined ? threshold - totalPoints : 0;
    }
    /**
     * Get next Pioneer tier
     */
    getNextTier(currentTier) {
        const tierOrder = ["pioneer", "active_pioneer", "contributing_pioneer", "founding_pioneer"];
        const currentIndex = tierOrder.indexOf(currentTier);
        if (currentIndex === -1 || currentIndex === tierOrder.length - 1) {
            return null;
        }
        return tierOrder[currentIndex + 1] ?? null;
    }
    /**
     * Get discount percentage for Pioneer tier
     */
    getTierDiscount(tier) {
        const discounts = {
            pioneer: 0,
            active_pioneer: 50,
            contributing_pioneer: 75,
            founding_pioneer: 100,
        };
        return discounts[tier] || 0;
    }
    /**
     * Get benefits for Pioneer tier
     */
    getTierBenefits(tier) {
        const benefits = {
            pioneer: ["Pioneer badge", "Community access"],
            active_pioneer: ["Pioneer badge", "Community access", "50% discount on Pro plan"],
            contributing_pioneer: ["Pioneer badge", "Community access", "75% discount on Pro plan", "Priority support"],
            founding_pioneer: [
                "Pioneer badge",
                "Community access",
                "Lifetime Pro access",
                "Priority support",
                "Founding member recognition",
            ],
        };
        return benefits[tier] || [];
    }
    /**
     * Compare two tiers (returns -1, 0, or 1)
     */
    compareTiers(userTier, requiredTier) {
        const tierOrder = ["free", "pro", "team", "enterprise"];
        const userIndex = tierOrder.indexOf(userTier);
        const requiredIndex = tierOrder.indexOf(requiredTier);
        return userIndex - requiredIndex;
    }
    /**
     * Map feature to actual usage from usage_limits table (ENT-001)
     * Maps feature names to database columns for usage tracking
     */
    getFeatureUsage(feature, usageData) {
        if (!usageData) {
            return 0;
        }
        // Map features to usage_limits table columns
        // This mapping aligns with the schema in packages/platform/src/db/schema/postgres.ts
        switch (feature) {
            case "cloud_backup":
                return usageData.snapshotsUsed || 0;
            case "api_access":
                return usageData.apiCallsUsed || 0;
            // Features without usage tracking (binary access)
            case "advanced_analytics":
            case "unlimited_workspaces":
            case "cli_full_features":
            case "team_dashboard":
            case "multi_workspace":
            case "sso_authentication":
            case "audit_logs":
            case "priority_support":
            case "custom_retention":
                return 0; // No usage tracking for these features
            default:
                return 0;
        }
    }
}
/**
 * Singleton instance of EntitlementsService
 * Used for cache coherence across webhook handlers and API routes
 */
export const entitlementsService = new EntitlementsServiceImpl();
