/**
 * Trial Schema
 * Tracks user trial periods for Pro features
 */

import { relations } from "drizzle-orm";
import { boolean, index, json, pgEnum, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
import { user } from "../postgres";

export const trialStatusEnum = pgEnum("trial_status", ["active", "expired", "converted", "canceled"]);

export const trials = pgTable(
	"trials",
	{
		id: text("id")
			.primaryKey()
			.$defaultFn(() => nanoid()),
		userId: text("user_id")
			.notNull()
			.unique()
			.references(() => user.id, { onDelete: "cascade" }),
		status: trialStatusEnum("status").notNull().default("active"),
		startedAt: timestamp("started_at").notNull().defaultNow(),
		endsAt: timestamp("ends_at").notNull(),
		convertedAt: timestamp("converted_at"), // When trial converted to paid subscription
		canceledAt: timestamp("canceled_at"),
		features: json("features")
			.$type<string[]>()
			.default(["cloud_backup", "api_access", "advanced_analytics", "priority_support"]),
		autoExtended: boolean("auto_extended").notNull().default(false), // Whether trial was auto-extended
		extensionReason: text("extension_reason"), // Reason for extension (e.g., 'pioneer_benefit', 'support_request')
		metadata: json("metadata").$type<Record<string, unknown>>(),
		createdAt: timestamp("created_at").notNull().defaultNow(),
		updatedAt: timestamp("updated_at").notNull().defaultNow(),
	},
	(table) => [
		index("trials_user_id_idx").on(table.userId),
		index("trials_status_idx").on(table.status),
		index("trials_ends_at_idx").on(table.endsAt),
	],
);

export const trialsRelations = relations(trials, ({ one }) => ({
	user: one(user, {
		fields: [trials.userId],
		references: [user.id],
	}),
}));

export type Trial = typeof trials.$inferSelect;
export type NewTrial = typeof trials.$inferInsert;
