// ESM imports fixed for Node.js v22+
import { eq } from "drizzle-orm";
import { z as zod } from "zod";
import { combinedSchema, db } from "../client.js";
const { user, account } = combinedSchema;
// Add input validation schema
const searchUsersSchema = zod.object({
    query: zod.string().min(1).max(100).optional(),
    limit: zod.number().min(1).max(100).default(50),
    offset: zod.number().min(0).default(0),
});
export async function getUsers({ limit, offset, query }) {
    if (!db) {
        throw new Error("Database not available");
    }
    // Validate input parameters
    const validatedParams = searchUsersSchema.parse({ query, limit, offset });
    // Use validated and sanitized query parameter if provided
    const whereClause = query
        ? // biome-ignore lint/suspicious/noExplicitAny: Drizzle query builder callback
            (user, { like, sql }) => like(user.name, sql `${"%"}${validatedParams.query}${"%"}`)
        : undefined;
    return await db.query.user.findMany({
        where: whereClause,
        limit: validatedParams.limit,
        offset: validatedParams.offset,
    });
}
export async function countAllUsers() {
    if (!db) {
        throw new Error("Database not available");
    }
    return db.$count(user);
}
export async function getUserById(id) {
    if (!db) {
        throw new Error("Database not available");
    }
    return await db.query.user.findFirst({
        // biome-ignore lint/suspicious/noExplicitAny: Drizzle query builder callback
        where: (user, { eq }) => eq(user.id, id),
    });
}
export async function getUserByEmail(email) {
    if (!db) {
        throw new Error("Database not available");
    }
    return await db.query.user.findFirst({
        // biome-ignore lint/suspicious/noExplicitAny: Drizzle query builder callback
        where: (user, { eq }) => eq(user.email, email),
    });
}
export async function createUser({ email, name, role, emailVerified, onboardingComplete, }) {
    if (!db) {
        throw new Error("Database not available");
    }
    const result = await db
        .insert(user)
        .values({
        email,
        name,
        role,
        emailVerified,
        onboardingComplete,
        createdAt: new Date(),
        updatedAt: new Date(),
    })
        .returning({
        id: user.id,
    });
    const firstResult = result[0];
    if (!firstResult) {
        throw new Error("Failed to create user");
    }
    const { id } = firstResult;
    const newUser = await getUserById(id);
    return newUser;
}
export async function getAccountById(id) {
    if (!db) {
        throw new Error("Database not available");
    }
    return await db.query.account.findFirst({
        // biome-ignore lint/suspicious/noExplicitAny: Drizzle query builder callback
        where: (account, { eq }) => eq(account.id, id),
    });
}
export async function createUserAccount({ userId, providerId, accountId, hashedPassword, }) {
    if (!db) {
        throw new Error("Database not available");
    }
    const result = await db
        .insert(account)
        .values({
        userId,
        accountId,
        providerId,
        createdAt: new Date(),
        updatedAt: new Date(),
        password: hashedPassword,
    })
        .returning({
        id: account.id,
    });
    const firstResult = result[0];
    if (!firstResult) {
        throw new Error("Failed to create account");
    }
    const { id } = firstResult;
    const newAccount = await getAccountById(id);
    return newAccount;
}
export async function updateUser(updatedUser) {
    if (!db) {
        throw new Error("Database not available");
    }
    return db.update(user).set(updatedUser).where(eq(user.id, updatedUser.id));
}
